"""Validation of a multi-party entropy vector against the classical entropy
inequalities, and detection of non-geometric vectors via the five-party
cyclic inequality.

Subsets of the p parties are encoded as bitmasks; union is bitwise OR and
disjointness is bitwise AND equal to zero.
"""

from __future__ import annotations

from typing import Dict, List, Sequence, Tuple

Vector = Sequence[int]


def disjoint_pairs(p: int):
    n = 1 << p
    for X in range(n):
        for Y in range(n):
            if X & Y == 0:
                yield X, Y


def disjoint_triples(p: int):
    n = 1 << p
    for X in range(n):
        for Y in range(n):
            if X & Y:
                continue
            for Z in range(n):
                if (Y & Z) or (X & Z):
                    continue
                yield X, Y, Z


def violations(S: Vector, p: int = 5) -> Dict[str, List[Tuple[int, ...]]]:
    """All violated instances of the four classical families.

    Cost O(8^p); for p = 5 that is 32768 instances per triple-family.
    """
    out: Dict[str, List[Tuple[int, ...]]] = {
        "subadditivity": [], "strong subadditivity": [],
        "weak monotonicity": [], "monogamy": []}
    for X, Y in disjoint_pairs(p):
        if S[X | Y] > S[X] + S[Y]:
            out["subadditivity"].append((X, Y))
    for X, Y, Z in disjoint_triples(p):
        if S[X | Y | Z] + S[Y] > S[X | Y] + S[Y | Z]:
            out["strong subadditivity"].append((X, Y, Z))
        if S[X] + S[Z] > S[X | Y] + S[Y | Z]:
            out["weak monotonicity"].append((X, Y, Z))
        if S[X | Y | Z] + S[X] + S[Y] + S[Z] > S[X | Y] + S[Y | Z] + S[X | Z]:
            out["monogamy"].append((X, Y, Z))
    return out


def cyclic_slack(S: Vector) -> int:
    """RHS - LHS of the five-party cyclic inequality; negative means the
    vector is realised by no bulk geometry."""
    pairs = [0b00011, 0b00110, 0b01100, 0b11000, 0b10001]
    triples = [0b00111, 0b01110, 0b11100, 0b11001, 0b10011]
    lhs = sum(S[m] for m in pairs) + S[0b11111]
    rhs = sum(S[m] for m in triples)
    return rhs - lhs


def report(S: Vector, name: str = "vector") -> None:
    v = violations(S)
    print(f"--- {name} ---")
    for family, insts in v.items():
        print(f"  {family:22s}: "
              + ("all instances hold" if not insts
                 else f"{len(insts)} violations, e.g. {insts[0]}"))
    slack = cyclic_slack(S)
    print(f"  cyclic inequality     : slack {slack}"
          + ("  -> NO BULK GEOMETRY REALISES THIS VECTOR" if slack < 0 else ""))


WITNESS: List[int] = [0, 3, 2, 5, 4, 5, 6, 5, 2, 5, 4, 7, 6, 6, 7, 5,
                      3, 6, 5, 7, 5, 4, 6, 4, 4, 5, 6, 6, 4, 3, 5, 2]


def cycle_geometry_vector() -> List[int]:
    """Min-cut entropies of the five-cycle of unit throats: S(X) is the number
    of cycle edges leaving X.  A genuinely geometric vector, and one that
    saturates the cyclic inequality."""
    S = []
    for m in range(32):
        S.append(sum(1 for i in range(5)
                     if ((m >> i) & 1) != ((m >> ((i + 1) % 5)) & 1)))
    return S


if __name__ == "__main__":
    report(WITNESS, "witness vector S_w")
    report(cycle_geometry_vector(), "five-cycle geometry")
